panel.css:
.ds-panel {
  background: #101012;
  border: 1px solid #26262b;
  border-radius: 12px;
  overflow: hidden;
}
.ds-panel-header {
  padding: 12px 16px;
  border-bottom: 1px solid #26262b;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #8a909c;
}
.ds-panel-body {
  padding: 16px;
  color: #e5e7eb;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
}

button-primary.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid #34d399;
  color: #34d399;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.ds-btn-primary:hover {
  background: rgba(52, 211, 153, 0.1);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid #34d399;
  outline-offset: 2px;
}
.ds-btn-primary:active {
  background: rgba(52, 211, 153, 0.2);
  transform: scale(0.98);
}

button-ghost.css:
.ds-btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid #26262b;
  color: #aab0bb;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  transition: border-color 0.15s, color 0.15s, background 0.15s;
}
.ds-btn-ghost:hover {
  border-color: #8a909c;
  color: #e5e7eb;
  background: #16161a;
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid #56b6c8;
  outline-offset: 2px;
}

button-danger.css:
.ds-btn-danger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid #e5645f;
  color: #e5645f;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s;
}
.ds-btn-danger:hover {
  background: rgba(229, 100, 95, 0.1);
}
.ds-btn-danger:focus-visible {
  outline: 2px solid #e5645f;
  outline-offset: 2px;
}

label-mono.css:
.ds-label-mono {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  line-height: 1.2;
  color: #8a909c;
}

metric-row.css:
.ds-metric-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  font-family: 'JetBrains Mono', Menlo, monospace;
  font-size: 11px;
  line-height: 1.4;
}
.ds-metric-label { color: #8a909c; }
.ds-metric-value { color: #e5e7eb; font-weight: 500; }
.ds-metric-green { color: #34d399; }
.ds-metric-amber { color: #d9a441; }
.ds-metric-red { color: #e5645f; }
.ds-metric-cyan { color: #56b6c8; }

sim-node.css:
.ds-simnode {
  position: relative;
  min-width: 190px;
  padding: 10px 12px 8px;
  border: 2px solid #a855f7;
  background: #101012;
  font-family: 'Inter', system-ui, sans-serif;
}
.ds-simnode-api { border-color: #a855f7; }
.ds-simnode-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.01em;
}
.ds-node-replicas {
  margin-left: auto;
  padding: 2px 4px;
  background: #2f2f36;
  color: #67e8f9;
  font-family: 'JetBrains Mono', Menlo, monospace;
  font-size: 10px;
  font-weight: 700;
  border-radius: 2px;
}
.ds-simnode-metrics {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ds-simnode-util {
  margin-top: 6px;
  height: 6px;
  background: #2f2f36;
  overflow: hidden;
}
.ds-simnode-util-bar {
  height: 100%;
  transition: width 0.3s ease-out, background 0.3s ease-out;
}

util-bar.css:
.ds-util-container {
  height: 6px;
  background: #2f2f36;
  overflow: hidden;
  border-radius: 0;
}
.ds-util-bar {
  height: 100%;
  transition: width 0.3s ease-out, background 0.3s ease-out;
}
